import sys


def rank(v, vals):
    return sum(1 for u in vals if u < v)


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pts = []
    for i in range(n):
        pts.append((int(data[1 + 2 * i]), int(data[2 + 2 * i])))
    dx = []
    dy = []
    for x, y in pts:
        if x not in dx:
            dx.append(x)
        if y not in dy:
            dy.append(y)
    h, w = len(dy), len(dx)
    out = [f'{h} {w}']
    for r in range(h):
        row = []
        for c in range(w):
            cnt = 0
            for x, y in pts:
                if rank(y, dy) == r and rank(x, dx) == c:
                    cnt += 1
            row.append(str(cnt))
        out.append(' '.join(row))
    print('\n'.join(out))


main()
